9:*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101719;color:var(--ink);font-family:'DM Sans',sans-serif}body{display:grid;place-items:center;user-select:none}#game{position:relative;width:min(100vw,160vh);height:min(100vh,62.5vw);max-width:1600px;max-height:1000px;overflow:hidden;background:#152023;box-shadow:0 20px 100px #000b;isolation:isolate}canvas{display:block;width:100%;height:100%;cursor:crosshair}.grain{position:absolute;inset:0;pointer-events:none;opacity:.10;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.82' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.32'/%3E%3C/svg%3E");mix-blend-mode:screen;z-index:3}.vignette{position:absolute;inset:0;pointer-events:none;background:radial-gradient(ellipse at center,transparent 45%,rgba(5,9,10,.64) 100%);z-index:2}.hud{position:absolute;inset:0;pointer-events:none;z-index:4}.topbar{position:absolute;top:24px;left:30px;right:30px;display:flex;justify-content:space-between;align-items:flex-start}.brand{font-family:Cinzel,serif;letter-spacing:.19em;font-size:12px;color:#d7c6a1;text-shadow:0 2px 8px #000}.brand b{display:block;font-weight:500;letter-spacing:.28em;font-size:9px;color:#87918a;margin-top:5px}.objective{position:absolute;top:23px;left:50%;transform:translateX(-50%);text-align:center;min-width:330px}.objective .label{font-size:9px;letter-spacing:.28em;color:#d4ad67;text-transform:uppercase}.objective h2{font:500 18px Cinzel,serif;margin:5px 0 0;text-shadow:0 2px 8px #000}.rightstats{display:flex;gap:15px;align-items:flex-start}.meter{width:125px}.meter-label{display:flex;justify-content:space-between;font-size:9px;letter-spacing:.16em;color:#aab1a7;text-transform:uppercase;margin-bottom:6px}.meter-track{height:4px;background:#d8d2ba30;border:1px solid #d8d2ba1a}.meter-fill{height:100%;width:100%;background:#c59c5e;transition:width .25s}.health .meter-fill{background:#a95848}.sigils{position:absolute;left:30px;bottom:27px;font-size:10px;letter-spacing:.18em;color:#a9b0a7}.sigils strong{font:500 15px Cinzel,serif;color:#e3c179;margin-left:10px}.controls{position:absolute;right:30px;bottom:25px;display:flex;gap:12px;color:#b1b8ae;font-size:9px;letter-spacing:.08em}.key{display:inline-grid;place-items:center;min-width:21px;height:20px;padding:0 5px;border:1px solid #c9c4af66;background:#101617aa;color:#e3dbc6;border-radius:3px;margin-right:4px;font-size:9px}.toast{position:absolute;left:50%;top:75px;transform:translate(-50%,-10px);opacity:0;color:#e5d7b8;font:500 13px Cinzel,serif;letter-spacing:.08em;text-shadow:0 2px 8px #000;transition:.3s}.toast.show{opacity:1;transform:translate(-50%,0)}.alert{position:absolute;top:112px;left:50%;transform:translateX(-50%);font:500 11px Cinzel,serif;letter-spacing:.3em;color:#e98b6f;opacity:0;transition:.3s;text-shadow:0 0 14px #b33}.alert.show{opacity:1}.modal{position:absolute;inset:0;z-index:8;display:grid;place-items:center;background:linear-gradient(90deg,rgba(8,14,16,.89),rgba(8,14,16,.43)),radial-gradient(ellipse at 70% 45%,transparent,rgba(0,0,0,.4));transition:opacity .55s,visibility .55s}.modal.hidden{opacity:0;visibility:hidden;pointer-events:none}.card{width:min(580px,88%);padding:48px 54px 40px;border-left:1px solid #d3a75c;border-top:1px solid #d3a75c35;background:linear-gradient(135deg,rgba(18,27,29,.92),rgba(14,20,21,.78));box-shadow:0 20px 70px #0008;position:relative}.eyebrow{font-size:10px;letter-spacing:.34em;color:#d5ae6a;text-transform:uppercase}.card h1{font:500 clamp(36px,5vw,62px)/1.02 Cinzel,serif;letter-spacing:.05em;color:#e8dfc9;margin:15px 0 8px}.card h1 span{display:block;color:#b7915d}.subtitle{font:italic 16px Cinzel,serif;color:#aeb1a6;margin:0 0 23px}.story{font-size:13px;line-height:1.75;color:#b4b8ac;max-width:430px}.story em{font-style:normal;color:#e1c080}.mission{display:flex;gap:12px;margin:22px 0 28px;color:#a7afa5;font-size:11px;line-height:1.6}.seal{color:#d7ad64;font:22px Cinzel,serif}.button{border:1px solid #c99d5c;background:#c99d5c;color:#172022;font:600 10px 'DM Sans',sans-serif;letter-spacing:.22em;text-transform:uppercase;padding:14px 21px;cursor:pointer;transition:.2s}.button:hover{background:#e2c47f;box-shadow:0 0 24px #d4ad6744}.smallnote{color:#78817b;font-size:9px;letter-spacing:.1em;margin-left:15px}.footer{position:absolute;bottom:18px;left:25px;right:25px;display:flex;justify-content:space-between;color:#6d7772;font-size:8px;letter-spacing:.18em}.corner{position:absolute;width:18px;height:18px;border-color:#d4ad6766}.c1{right:13px;top:13px;border-right:1px solid;border-top:1px solid}.c2{right:13px;bottom:13px;border-right:1px solid;border-bottom:1px solid}.mobile-help{display:none}
