82:function reset(){player.x=135;player.y=1090;player.hp=100;player.blink=0;player.has=0;player.hidden=false;player.invuln=0;seals.forEach(s=>s.got=false);guards.forEach((g,i)=>{g.x=g.route[0][0];g.y=g.route[0][1];g.i=0;g.alert=0;g.stun=0;g.state='patrol'});won=false;gameOver=false;ui.seals.textContent='0 / 3';ui.health.style.width='100%';ui.objective.textContent='Найдите три латунные печати';ui.title.innerHTML='Тень <span>Грейхейвена</span>';ui.kicker.textContent='Город затаил дыхание';ui.subtitle.textContent='Стелс-приключение в затопленном квартале';ui.story.textContent='Лорд-регент запер старую гавань. Найдите три латунные печати, чтобы открыть путь к маяку и узнать правду, скрытую под городом. Держитесь теней: у этого города долгая память.';ui.mission.innerHTML='<span class="seal">◈</span><span>Соберите <em>три латунные печати</em> и доберитесь до маяка. Избегайте стражи или оглушайте её теневым рывком.</span>';ui.play.textContent='Войти в квартал  →';ui.mission.style.display='flex'}
87:function finish(success){running=false;won=success;gameOver=!success;ui.modal.classList.remove('hidden');ui.kicker.textContent=success?'ГОРОД ЗАПОМНИТ ЭТУ НОЧЬ':'СТРАЖА ВАС НАШЛА';ui.title.innerHTML=success?'Тихая <span>расплата</span>':'Потерянный в <span>тумане</span>';ui.subtitle.textContent=success?'Грейхейвен встречает новое утро.':'Тени смыкаются вокруг вас.';ui.story.textContent=success?'Вы обошли стражу и унесли правду с собой. Где-то за гаванью звонит первый колокол.':'Силы иссякли. Стража утаскивает вас в туман. Но всегда есть другой путь.';ui.mission.style.display='none';ui.play.textContent='Играть снова  →';}
